import{_ as r,c as a,o as t,a5 as c}from"./chunks/framework.DuCYAsAJ.js";const b=JSON.parse('{"title":"Search RPC 服务","description":"","frontmatter":{"title":"Search RPC 服务","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#6","branch":"main","level":0,"order":6},"headers":[],"relativePath":"posts/projects/zfeed/06-search-rpc-service/index.md","filePath":"posts/projects/zfeed/06-search-rpc-service/index.md","lastUpdated":1779632679000}'),o={name:"posts/projects/zfeed/06-search-rpc-service/index.md"};function i(l,e,h,n,p,d){return t(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="search-rpc-服务" tabindex="-1">Search RPC 服务 <a class="header-anchor" href="#search-rpc-服务" aria-label="Permalink to &quot;Search RPC 服务&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/.gitignore" target="_blank" rel="noreferrer">.gitignore</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/search/search.api" target="_blank" rel="noreferrer">app/front/doc/search/search.api</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/types/types.go" target="_blank" rel="noreferrer">app/front/internal/types/types.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config_env_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config_env_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/svc/servicecontext.go" target="_blank" rel="noreferrer">app/rpc/search/internal/svc/servicecontext.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/proto/search.proto" target="_blank" rel="noreferrer">app/rpc/search/proto/search.proto</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/search/search.pb.go" target="_blank" rel="noreferrer">app/rpc/search/search/search.pb.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env" target="_blank" rel="noreferrer">deploy/.env</a></li></ul></details><p><code>search-rpc</code> 服务为 zfeed 生态中的用户和内容提供高性能全文搜索能力。它通过统一 gRPC 接口封装复杂搜索逻辑，包括查询归一化、多模式排序和稳定分页。为了保证低延迟和稳定性能，它使用多层缓存架构，包括结果快照和实体文档缓存。</p><h2 id="服务角色与架构" tabindex="-1">服务角色与架构 <a class="header-anchor" href="#服务角色与架构" aria-label="Permalink to &quot;服务角色与架构&quot;">​</a></h2><p>该服务是平台的主要搜索引擎。它设计为对底层搜索后端无感，当前实现主要使用 MySQL 全文搜索，并带有增强计分逻辑。它还与 <code>interaction-rpc</code> 集成，用于补全搜索结果中的查看者相关状态，例如 <code>is_following</code>。</p><h3 id="搜索服务工作流" tabindex="-1">搜索服务工作流 <a class="header-anchor" href="#搜索服务工作流" aria-label="Permalink to &quot;搜索服务工作流&quot;">​</a></h3><p>下图展示请求进入 <code>SearchService</code> 后，如何流转到最终补全后的响应。</p><p>“搜索请求流程”</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchuserslogic.go#L1-L50" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchuserslogic.go#1-50</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/svc/servicecontext.go#L63-L75" target="_blank" rel="noreferrer">app/rpc/search/internal/svc/servicecontext.go#63-75</a></p><h2 id="关键组件" tabindex="-1">关键组件 <a class="header-anchor" href="#关键组件" aria-label="Permalink to &quot;关键组件&quot;">​</a></h2><p>该服务由多个专门的内部包组成：</p><table tabindex="0"><thead><tr><th>组件</th><th>职责</th><th>代码实体</th></tr></thead><tbody><tr><td>Service Context</td><td>管理 Redis、MySQL 和 RPC 客户端等依赖。</td><td><code>svc.ServiceContext</code> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/svc/servicecontext.go#L19-L26" target="_blank" rel="noreferrer">app/rpc/search/internal/svc/servicecontext.go#19-26</a></td></tr><tr><td>Query Normalizer</td><td>清洗、分词并哈希原始用户输入。</td><td><code>querynorm.Normalizer</code> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/svc/servicecontext.go#L25-L25" target="_blank" rel="noreferrer">app/rpc/search/internal/svc/servicecontext.go#25</a></td></tr><tr><td>Backend Factory</td><td>抽象底层搜索引擎，例如 MySQL。</td><td><code>backend.Factory</code> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/svc/servicecontext.go#L24-L24" target="_blank" rel="noreferrer">app/rpc/search/internal/svc/servicecontext.go#24</a></td></tr><tr><td>Observability</td><td>追踪搜索延迟、缓存命中率和慢查询。</td><td><code>logic.observeSearch</code> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L93-L159" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#93-159</a></td></tr></tbody></table><h3 id="代码实体映射" tabindex="-1">代码实体映射 <a class="header-anchor" href="#代码实体映射" aria-label="Permalink to &quot;代码实体映射&quot;">​</a></h3><p>该图将逻辑搜索概念映射到代码库中的具体实现。</p><p>“搜索逻辑到代码的映射”</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/svc/servicecontext.go#L19-L26" target="_blank" rel="noreferrer">app/rpc/search/internal/svc/servicecontext.go#19-26</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L73-L91" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#73-91</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/search/search.pb.go#L62-L65" target="_blank" rel="noreferrer">app/rpc/search/search/search.pb.go#62-65</a></p><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2><h3 id="_1-稳定分页与-pagetoken" tabindex="-1">1. 稳定分页与 PageToken <a class="header-anchor" href="#_1-稳定分页与-pagetoken" aria-label="Permalink to &quot;1. 稳定分页与 PageToken&quot;">​</a></h3><p>为了防止搜索会话期间新内容发布导致“跳过结果”或“重复结果”，服务支持 <code>SnapshotId</code> 与 <code>PageToken</code> 机制。这可以确保用户翻页过程中看到的列表，相对于搜索开始时刻保持一致。</p><ul><li>详情请参阅<a href="./01-search-logic-modes-pagination-and-hydration.html">搜索逻辑：模式、分页与补全</a>。</li></ul><h3 id="_2-多层缓存" tabindex="-1">2. 多层缓存 <a class="header-anchor" href="#_2-多层缓存" aria-label="Permalink to &quot;2. 多层缓存&quot;">​</a></h3><p>该服务实现了两层基于 Redis 的缓存策略：</p><ul><li>查询快照缓存：存储某个查询和页面对应的有序 ID 列表。</li><li>文档摘要缓存：存储实际实体数据（用户资料或内容元数据），避免补全阶段执行重型数据库 join。</li><li>详情请参阅<a href="./03-search-caching-query-cache-doc-cache-and-snapshots.html">搜索缓存：查询缓存、文档缓存与快照</a>。</li></ul><h3 id="_3-排序与计分" tabindex="-1">3. 排序与计分 <a class="header-anchor" href="#_3-排序与计分" aria-label="Permalink to &quot;3. 排序与计分&quot;">​</a></h3><p>搜索后端会基于以下因素组合计算 <code>rank_score</code>：</p><ul><li><code>text_score</code>：查询与标题/描述的相关性。</li><li><code>hot_score</code>：点赞、浏览等热度指标，用于优先展示高质量内容。</li><li>详情请参阅<a href="./02-search-backend-and-query-normalization.html">搜索后端与查询归一化</a>。</li></ul><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>服务行为由部署配置中的环境变量控制。</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><code>SEARCH_CACHE_ENABLED</code></td><td>启用/禁用 Redis 缓存层。</td><td><code>false</code></td></tr><tr><td><code>SEARCH_SNAPSHOT_ENABLED</code></td><td>启用稳定分页快照。</td><td><code>false</code></td></tr><tr><td><code>SEARCH_BACKEND</code></td><td>搜索引擎类型，例如 <code>mysql</code>。</td><td><code>mysql</code></td></tr><tr><td><code>SEARCH_QUERY_CACHE_TTL_SECONDS</code></td><td>页面级结果缓存 TTL。</td><td><code>60</code></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L25-L34" target="_blank" rel="noreferrer">deploy/.env#25-34</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go#L8-L22" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go#8-22</a></p><h2 id="子页面" tabindex="-1">子页面 <a class="header-anchor" href="#子页面" aria-label="Permalink to &quot;子页面&quot;">​</a></h2><ul><li><a href="./01-search-logic-modes-pagination-and-hydration.html">搜索逻辑：模式、分页与补全</a>：详细介绍端到端请求处理、模式选择（latest/relevance）和结果补全。</li><li><a href="./02-search-backend-and-query-normalization.html">搜索后端与查询归一化</a>：MySQL 全文搜索引擎、查询清洗和排序公式的实现。</li><li><a href="./03-search-caching-query-cache-doc-cache-and-snapshots.html">搜索缓存：查询缓存、文档缓存与快照</a>：Redis 缓存架构、TTL 抖动和快照生命周期的技术细节。</li></ul>',32)])])}const g=r(o,[["render",i]]);export{b as __pageData,g as default};
